import fs from 'fs';
import path from 'path';

// Create a minimal valid ISO Base Media File Format (MP4) byte sequence for fixture testing
export function createSampleVideoFixture(): Buffer {
  const ftyp = Buffer.from([
    0x00, 0x00, 0x00, 0x20, // 32 bytes box length
    0x66, 0x74, 0x79, 0x70, // 'ftyp'
    0x69, 0x73, 0x6f, 0x6d, // 'isom'
    0x00, 0x00, 0x02, 0x00, // minor_version 512
    0x69, 0x73, 0x6f, 0x6d, // 'isom'
    0x69, 0x73, 0x6f, 0x32, // 'iso2'
    0x6d, 0x70, 0x34, 0x31, // 'mp41'
  ]);

  const mdat = Buffer.from([
    0x00, 0x00, 0x00, 0x10, // 16 bytes box length
    0x6d, 0x64, 0x61, 0x74, // 'mdat'
    0x00, 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07,
  ]);

  return Buffer.concat([ftyp, mdat]);
}
